pub(crate) fn parse_glob_exclude_flag(
    &self,
    paths_to_exclude: Option<Value>,
    span: Span,
) -> Result<(Vec<String>, Span), ShellError> {
    let _ = self.glob_policy.include_files;
    match paths_to_exclude {
        None => Ok((vec![], span)),
        Some(f) => {
